import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        solve(n, mod);
        scanner.close();
    }

    public static void solve(int n, int mod) {
        if (n <= 3) {
            System.out.println(0);
            return;
        }
        int last_value = 17;
        int total_value = 17;
        int max_length = (n - 1) * (n - 2) / 2 + 1;
        int toggle_bit = 1;
        int[][] table = new int[2][max_length + 1];
        // Initialize the first row
        table[0][0] = 1;
        table[0][1] = 2;
        table[0][2] = 2;
        table[0][3] = 1;

        for (int m = 4; m < n; m++) {
            int total_pairs = m * (m - 1) / 2;
            total_value = (m + 1) * last_value;
            int partial_sum = 0;
            // Compute partial sums for table[toggle_bit]
            for (int i = 0; i < m; i++) {
                partial_sum += table[toggle_bit ^ 1][i];
                table[toggle_bit][i] = partial_sum % mod;
            }
            // Fill remaining entries
            for (int i = m; i <= total_pairs / 2; i++) {
                partial_sum += table[toggle_bit ^ 1][i];
                if (i - m >= 0) {
                    partial_sum -= table[toggle_bit ^ 1][i - m];
                }
                table[toggle_bit][i] = ((partial_sum % mod) + mod) % mod;
            }
            // Mirror the first half to second half
            for (int i = 0; i <= total_pairs / 2; i++) {
                table[toggle_bit][total_pairs - i] = table[toggle_bit][i];
            }
            int total_acc = 0;
            for (int i = 0; i < total_pairs; i++) {
                int temp_sum = 0;
                int start_idx = Math.max(1, -total_pairs + i + m + 2);
                for (int j = start_idx; j <= m; j++) {
                    int index = m + 2 - j + i;
                    if (index >= 0 && index <= total_pairs) {
                        temp_sum += j * table[toggle_bit][index];
                    }
                }
                total_acc += table[toggle_bit][i];
                total_acc %= mod;
                temp_sum %= mod;
                total_value += ((long) temp_sum * total_acc) % mod;
                total_value %= mod;
            }
            last_value = total_value;
            toggle_bit ^= 1;
        }
        System.out.println(total_value % mod);
    }
}
